package cn.pi.bilipoints;
import android.graphics.*;import android.os.*;import android.widget.*;import android.util.LruCache;import java.net.*;import java.io.*;import java.util.concurrent.*;
/** Only public official CDN assets; no cookies or authentication headers are sent. */
public final class ProfileImages {
 final ExecutorService pool=Executors.newFixedThreadPool(2);final Handler ui=new Handler(Looper.getMainLooper());final LruCache<String,Bitmap> cache=new LruCache<>(8);volatile boolean closed=false;
 public static String officialUrl(String raw){try{if(raw==null||raw.isEmpty())return "";if(raw.startsWith("//"))raw="https:"+raw;if(raw.startsWith("http://"))raw="https://"+raw.substring(7);URI u=new URI(raw);String h=u.getHost();if(!"https".equals(u.getScheme())||h==null||!(h.equals("hdslb.com")||h.endsWith(".hdslb.com"))||u.getUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443))return "";return u.toString();}catch(Exception e){return "";}}
 public void load(String raw,ImageView view,Runnable ready){String url=officialUrl(raw);if(url.equals(view.getTag()))return;view.setTag(url);if(url.isEmpty())return;Bitmap found=cache.get(url);if(found!=null){view.clearColorFilter();view.setImageBitmap(found);if(ready!=null)ready.run();return;}
  pool.execute(()->{Bitmap bmp=null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(10000);if(c.getResponseCode()!=200)return;ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2097152)return;out.write(b,0,n);}}byte[] bytes=out.toByteArray();BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);if(opts.outWidth<=0||opts.outHeight<=0)return;int sample=1;while(opts.outWidth/sample>512||opts.outHeight/sample>512)sample*=2;opts.inSampleSize=sample;opts.inJustDecodeBounds=false;bmp=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}if(bmp==null||closed)return;cache.put(url,bmp);final Bitmap result=bmp;ui.post(()->{if(!closed&&url.equals(view.getTag())){view.clearColorFilter();view.setImageBitmap(result);if(ready!=null)ready.run();}});});
 }
 public void close(){closed=true;pool.shutdownNow();ui.removeCallbacksAndMessages(null);cache.evictAll();}
}
